const markdown = $input.first().json.data?.markdown || '';
const company = $('Filter Active').item.json.company || 'Unknown';

const linkRegex = /\[([^\]]*)\]\((https?:\/\/[^)]+)\)/g;
const links = [];
let match;

while ((match = linkRegex.exec(markdown)) !== null) {
  links.push({ text: match[1].trim(), url: match[2].trim() });
}

// Skip images, PDFs, wp-content, case studies
const skipPatterns = [
  /\.(png|jpg|jpeg|gif|svg|pdf|webp)(\?|$)/i,
  /wp-content\/uploads/i,
  /case.?study/i,
  /^!\[/,
  /#/,           // ← ADD: skip anchor links (page sections)
  /culture/i,    // ← ADD
  /about/i,      // ← ADD
  /blog/i,       // ← ADD
  /insight/i,    // ← ADD
  /news/i,       // ← ADD
  /why-/i,       // ← ADD: catches why-happiest-minds etc
];

// Must match job URL patterns
// Must match job URL patterns
const jobPatterns = [
  /\/jobs?\//i,
  /\/careers?\//i,
  /\/openings?\//i,
  /\/apply/i,
  /\/vacancies/i,
  /\/positions?\//i,
  /\/hiring/i,
  /greenhouse\.io/i,
  /lever\.co/i,
  /workday\.com/i,
  /myworkdayjobs/i,
  /smartrecruiters/i,
  /naukri\.com/i,
  /darwinbox\.com/i,        // ← ADD
  /^https?:\/\/jobs\./i,    // ← ADD (catches jobs.happiestminds.com)
  /^https?:\/\/careers\./i, // ← ADD (catches careers.persistent.com etc)
  /\/candidate\//i,         // ← ADD
];
const jobLinks = links.filter(l => {
  const isSkip = skipPatterns.some(p => p.test(l.url) || p.test(l.text));
  const isJob = jobPatterns.some(p => p.test(l.url));
  return !isSkip && isJob;
}).slice(0, 5); // max 5 per company

if (jobLinks.length === 0) {
  return [{ json: { company, url: null, noJobs: true, linkText: 'No job links found' } }];
}

return jobLinks.map(l => ({
  json: { company, url: l.url, linkText: l.text, noJobs: false }
}));

