// ─────────────────────────────────────────────
// STEP 1: Load already-seen job URLs from sheet
// ─────────────────────────────────────────────
const seenItems = $input.all();
const seenUrls = new Set(
  seenItems
    .filter(item => item.json && item.json.job_url)
    .map(item => item.json.job_url)
);

// ─────────────────────────────────────────────
// STEP 2: Role keywords filter
// ─────────────────────────────────────────────
const ROLE_KEYWORDS = [
  'ai engineer', 'java developer', 'java backend', 'python developer',
  'full stack', 'fullstack', 'full-stack', 'backend developer',
  'associate software', 'software engineer', 'software developer',
  'ml engineer', 'machine learning', 'generative ai', 'llm engineer',
  'data engineer', 'react developer', 'node.js', 'nodejs',
  'web developer', 'application developer', 'fresher', 'graduate trainee',
  'graduate engineer', 'entry level', 'campus hire', '0-1 year',
  '0 to 1', 'freshers welcome', 'trainee engineer', 'junior developer',
  'junior engineer', 'associate engineer'
];

const SKIP_KEYWORDS = [
  'senior ', 'sr.', 'sr ', 'lead developer', 'engineering manager',
  'principal', 'director', ' vp ', 'head of', 'staff engineer',
  'architect', '3+ years', '5+ years', '4+ years', '7+ years', '10+ years',
  'spring boot', 'angular developer', '.net developer', 'c# developer',
  'qa engineer', 'scrum master', 'product manager', 'ux designer',
  'ui designer', 'salesforce developer', 'sap ', 'oracle dba',
  'site reliability', 'devops engineer', 'cloud architect'
];

function isRelevant(title, description) {
  const text = (title + ' ' + (description || '')).toLowerCase();
  const hasRole = ROLE_KEYWORDS.some(k => text.includes(k));
  const isSkip = SKIP_KEYWORDS.some(k => text.includes(k));
  return hasRole && !isSkip;
}

function normalize(title, company, url, location, description, source) {
  return {
    title: title || 'Unknown Role',
    company: company || 'Unknown Company',
    url: url || '',
    location: location || 'India',
    description: (description || '').replace(/<[^>]*>/g, '').substring(0, 400),
    source
  };
}

// ─────────────────────────────────────────────
// STEP 3: API Sources
// ─────────────────────────────────────────────
const API_SOURCES = [
  // Remotive — remote dev jobs globally
  { id: 'remotive', type: 'remotive', company: 'Various',
    url: 'https://remotive.com/api/remote-jobs?category=software-dev&limit=100' },

  // Greenhouse ATS — Indian product/startup companies
  { id: 'gh_freshworks',   type: 'greenhouse', company: 'Freshworks',   url: 'https://boards-api.greenhouse.io/v1/boards/freshworks/jobs' },
  { id: 'gh_krutrim',      type: 'greenhouse', company: 'Krutrim',      url: 'https://boards-api.greenhouse.io/v1/boards/krutrim/jobs' },
  { id: 'gh_hasura',       type: 'greenhouse', company: 'Hasura',       url: 'https://boards-api.greenhouse.io/v1/boards/hasura/jobs' },
  { id: 'gh_razorpay',     type: 'greenhouse', company: 'Razorpay',     url: 'https://boards-api.greenhouse.io/v1/boards/razorpay/jobs' },
  { id: 'gh_browserstack', type: 'greenhouse', company: 'BrowserStack', url: 'https://boards-api.greenhouse.io/v1/boards/browserstack/jobs' },
  { id: 'gh_postman',      type: 'greenhouse', company: 'Postman',      url: 'https://boards-api.greenhouse.io/v1/boards/postman/jobs' },
  { id: 'gh_meesho',       type: 'greenhouse', company: 'Meesho',       url: 'https://boards-api.greenhouse.io/v1/boards/meesho/jobs' },
  { id: 'gh_zepto',        type: 'greenhouse', company: 'Zepto',        url: 'https://boards-api.greenhouse.io/v1/boards/zepto/jobs' },
  { id: 'gh_groww',        type: 'greenhouse', company: 'Groww',        url: 'https://boards-api.greenhouse.io/v1/boards/groww/jobs' },

  // Lever ATS — startups & AI-first companies
  { id: 'lv_sarvam',    type: 'lever', company: 'Sarvam AI',  url: 'https://api.lever.co/v0/postings/sarvamai?mode=json' },
  { id: 'lv_yellow',    type: 'lever', company: 'Yellow.ai',  url: 'https://api.lever.co/v0/postings/yellowai?mode=json' },
  { id: 'lv_moengage',  type: 'lever', company: 'MoEngage',   url: 'https://api.lever.co/v0/postings/moengage?mode=json' },
  { id: 'lv_clevertap', type: 'lever', company: 'CleverTap',  url: 'https://api.lever.co/v0/postings/clevertap?mode=json' },
  { id: 'lv_sprinklr',  type: 'lever', company: 'Sprinklr',   url: 'https://api.lever.co/v0/postings/sprinklr?mode=json' },
  { id: 'lv_chargebee', type: 'lever', company: 'Chargebee',  url: 'https://api.lever.co/v0/postings/chargebee?mode=json' },
  { id: 'lv_zoho',      type: 'lever', company: 'Zoho',       url: 'https://api.lever.co/v0/postings/zoho?mode=json' }
];

// ─────────────────────────────────────────────
// STEP 4: Fetch + normalize + filter
// ─────────────────────────────────────────────
const today = new Date().toISOString().split('T')[0];
const allNewJobs = [];
const runSeenUrls = new Set(seenUrls); // working copy

for (const source of API_SOURCES) {
  try {
    const response = await fetch(source.url, {
      headers: { 'Accept': 'application/json', 'User-Agent': 'Mozilla/5.0' },
      signal: AbortSignal.timeout(12000)
    });
    if (!response.ok) continue;
    const data = await response.json();

    let jobs = [];

    if (source.type === 'remotive') {
      jobs = (data.jobs || []).map(j =>
        normalize(j.title, j.company_name, j.url,
          j.candidate_required_location, j.description, 'Remotive')
      );
    } else if (source.type === 'greenhouse') {
      jobs = (data.jobs || []).map(j =>
        normalize(j.title, source.company, j.absolute_url,
          j.location?.name, '', 'Greenhouse')
      );
    } else if (source.type === 'lever') {
      const arr = Array.isArray(data) ? data : [];
      jobs = arr.map(j =>
        normalize(j.text, source.company, j.hostedUrl,
          j.categories?.location, j.description, 'Lever')
      );
    }

    for (const job of jobs) {
      if (!job.url) continue;
      if (runSeenUrls.has(job.url)) continue;
      if (!isRelevant(job.title, job.description)) continue;
      allNewJobs.push({ ...job, date_found: today });
      runSeenUrls.add(job.url);
    }

  } catch (e) {
    console.log(`Skipped: ${source.id} — ${e.message}`);
  }
}

// ─────────────────────────────────────────────
// STEP 5: Return results
// ─────────────────────────────────────────────
if (allNewJobs.length === 0) {
  return [{ json: { no_new_jobs: true, message: 'No new matching jobs found today', date: today } }];
}

return allNewJobs.map(job => ({ json: job }));
